CREATE TABLE IF NOT EXISTS kategoriler(kategori_id INTEGER PRIMARY KEY AUTOINCREMENT,kategori_adi TEXT NOT NULL UNIQUE COLLATE NOCASE);
CREATE TABLE IF NOT EXISTS tedarikciler(id INTEGER PRIMARY KEY AUTOINCREMENT,firma_adi TEXT NOT NULL UNIQUE COLLATE NOCASE,yetkili_adsoyad TEXT NOT NULL,telefon TEXT NOT NULL UNIQUE,mail TEXT UNIQUE COLLATE NOCASE,adres TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS musteriler(id INTEGER PRIMARY KEY AUTOINCREMENT,ad_soyad TEXT NOT NULL,firma_adi TEXT,telefon TEXT NOT NULL UNIQUE,mail TEXT,adres TEXT);
CREATE TABLE IF NOT EXISTS yetkiler(yetki_id INTEGER PRIMARY KEY,yetki_adi TEXT NOT NULL UNIQUE);
INSERT OR IGNORE INTO yetkiler VALUES(1,'Yönetici'),(2,'Personel');
CREATE TABLE IF NOT EXISTS personeller(id INTEGER PRIMARY KEY AUTOINCREMENT,ad TEXT NOT NULL,soyad TEXT NOT NULL,telefon TEXT NOT NULL UNIQUE,mail TEXT,adres TEXT,kullanici_adi TEXT NOT NULL UNIQUE COLLATE NOCASE,sifre TEXT NOT NULL,yetki_id INTEGER NOT NULL REFERENCES yetkiler(yetki_id));
-- Parasal değerler kuruş olarak saklanır (fiyat sütunları).
CREATE TABLE IF NOT EXISTS urunler(urun_kodu INTEGER PRIMARY KEY AUTOINCREMENT,urun_adi TEXT NOT NULL UNIQUE COLLATE NOCASE,kategori_id INTEGER NOT NULL REFERENCES kategoriler(kategori_id),tedarikci_id INTEGER NOT NULL REFERENCES tedarikciler(id),stok_adedi INTEGER NOT NULL CHECK(stok_adedi>=0 AND stok_adedi<=2147483647),fiyat INTEGER NOT NULL CHECK(fiyat>=0 AND fiyat<=9999999999),aciklama TEXT);
CREATE TABLE IF NOT EXISTS satislar(satis_id INTEGER PRIMARY KEY AUTOINCREMENT,musteri_id INTEGER NOT NULL REFERENCES musteriler(id),personel_id INTEGER NOT NULL REFERENCES personeller(id),islemTarihi TEXT NOT NULL,notlar TEXT);
CREATE TABLE IF NOT EXISTS satis_detaylari(satis_detay_id INTEGER PRIMARY KEY AUTOINCREMENT,satis_id INTEGER NOT NULL REFERENCES satislar(satis_id) ON DELETE CASCADE,urun_kodu INTEGER NOT NULL REFERENCES urunler(urun_kodu),miktar INTEGER NOT NULL CHECK(miktar>0),fiyat INTEGER NOT NULL CHECK(fiyat>=0),UNIQUE(satis_id,urun_kodu));
CREATE INDEX IF NOT EXISTS ix_satis_detay_urun ON satis_detaylari(urun_kodu);
